docker exec 1ff4d45778dcfbc58cac36e4ae6a1a0425d23c835ad63cdb9be5cb0b8091b45a mongosh --quiet --host mongo:27017 --eval "const d=db.getSiblingDB('attendance_db'),sid=3,rid=null;
const reqFilter=rid===null?{}:{_id:new ObjectId(rid),student_id:sid};
const attFilter=rid===null?{}:{request_id:rid};
const outFilter=rid===null?{event_type:'excuse.requested'}:{event_type:'excuse.requested',payload:{'$regex':rid}};
print(JSON.stringify({
  excuseTickets:d.excuse_tickets.countDocuments({student_id:sid}),
  receipts:d.student_request_receipts.countDocuments({student_id:sid,command_kind:'EXCUSE'}),
  attachments:d.request_attachments.countDocuments({owner_student_id:sid}),
  outboxRequested:d.attendance_outbox.countDocuments({event_type:'excuse.requested'}),
  requestTickets:d.excuse_tickets.countDocuments(reqFilter),
  requestTicketStatus:rid===null?null:(d.excuse_tickets.find(reqFilter,{_id:1,status:1}).sort({_id:1}).toArray().map(x=>x.status)[0]??null),
  requestAttachments:d.request_attachments.find(attFilter,{_id:1,name:1,type:1,size:1,sha256:1,state:1,uploaded_at:1,expires_at:1,expired_at:1,request_id:1,position:1}).sort({position:1}).toArray().map(x=>({id:String(x._id),name:x.name,content_type:x.type,size:x.size,sha256:x.sha256,state:x.state,uploaded_at:x.uploaded_at==null?null:new Date(x.uploaded_at).toISOString(),expires_at:x.expires_at==null?null:new Date(x.expires_at).toISOString(),expired_at:x.expired_at==null?null:new Date(x.expired_at).toISOString(),request_id:x.request_id})),
  requestOutbox:d.attendance_outbox.find(outFilter,{_id:1,event_type:1,payload:1,status:1}).toArray().map(x=>{const envelope=JSON.parse(x.payload),payload=envelope.payload||{};return {id:String(x._id),event_type:x.event_type,status:x.status,payloadTicketId:payload.ticket_id==null?null:String(payload.ticket_id),payloadAttachments:(payload.attachments||[]).map(a=>({id:a.id,name:a.name,content_type:a.content_type,size:a.size,sha256:a.sha256,state:a.state,uploaded_at:a.uploaded_at,expires_at:a.expires_at,expired_at:a.expired_at==null?null:a.expired_at}))}})
}));"

